import { ClaimSchema } from "@sonar-ai/core";
import { z } from "zod";
import type { AgentDef } from "../runner/types";

/**
 * A claim as the MODEL produces it — no ID. Derived from the core `Claim` schema
 * so it cannot drift. `finalize` assigns the stable claim ID. Shared by every
 * agent whose output carries evidence-linked claims.
 */
export const ClaimDraftSchema = ClaimSchema.omit({ id: true });
export type ClaimDraft = z.infer<typeof ClaimDraftSchema>;

/**
 * A committee agent, from the agents lane's point of view.
 *
 * The model produces a **draft** (`TDraft`): semantic content only, no IDs. A
 * pure `finalize` turns that draft into the core output type (`TOutput`),
 * assigning deterministic IDs. This keeps structured output robust (the model
 * never invents an ID) and keeps IDs testable and stable across replays.
 *
 * The orchestrator runs `def` through an `AgentRunner`, then calls `finalize`:
 *
 *   const draft = (await runner.run(agent.def, ctx)).output;
 *   const output = agent.finalize(draft, ctx);   // core type, ready for the gate
 *
 * Draft schemas are DERIVED from the core output schemas (via `.omit`), so they
 * can never drift from the contract.
 */
export interface Agent<TContext, TDraft, TOutput> {
  def: AgentDef<TContext, TDraft>;
  finalize(draft: TDraft, context: TContext): TOutput;
}

import {
  FundamentalReportSchema,
  type Evidence,
  type FundamentalReport,
  type Instrument,
} from "@sonar-ai/core";
import { z } from "zod";
import { ClaimDraftSchema, type Agent } from "./types";

/**
 * Fundamental Analyst — evaluates ONE company's business quality, valuation,
 * financial strength, catalysts, and risks from an isolated evidence pack.
 *
 * Authority: assess asset quality and valuation. It does NOT size positions,
 * discuss portfolio allocation, or read the risk report or other agents' output.
 * The orchestrator calls it once per selected instrument.
 */

/** What the Fundamental Analyst is allowed to see. Populated by the orchestrator. */
export interface FundamentalContext {
  /** The single company under review. */
  instrument: Instrument;
  /**
   * The isolated, pre-fetched evidence pack (fundamentals, filings, news, and
   * any price/valuation facts). Deliberately the ONLY window this agent has —
   * it never sees the mandate, the risk report, or other agents' output, so it
   * cannot drift toward sizing decisions.
   */
  evidence: Evidence[];
  /** A prior thesis on this instrument, if the fund already holds a view. */
  priorThesis?: string | null;
}

// The model produces content only — no IDs. Drafts are derived from the core
// schemas so they cannot drift from the contract.
export const FundamentalReportDraftSchema = FundamentalReportSchema.omit({
  id: true,
  instrumentId: true,
  claims: true,
}).extend({ claims: z.array(ClaimDraftSchema) });
export type FundamentalReportDraft = z.infer<typeof FundamentalReportDraftSchema>;

// ── First-draft prompt (Axel owns the final wording) ─────────────────────────

const INSTRUCTIONS = `You are the Fundamental Analyst on an investment committee.

Evaluate exactly ONE company using ONLY the evidence provided. Assess:
- quality: the durability of the business and its competitive position;
- valuation: whether the price is justified by fundamentals;
- financialStrength: balance sheet, margins, cash generation;
- catalysts: concrete events that could re-rate the asset;
- risks: what could impair the thesis.

Then list claims. Every claim MUST cite one or more evidenceIds drawn ONLY from
the provided pack — never invent an ID or a fact not supported by the evidence.
Mark each claim's stance as "bull", "bear", "neutral", or "context".

Do NOT size positions, recommend a weight, or discuss the rest of the portfolio —
that is the Portfolio Manager's job. Return only the required JSON.`;

function buildInput(ctx: FundamentalContext): string {
  const evidenceBlock =
    ctx.evidence
      .map(
        (e) =>
          `- ${e.id} | ${e.title} | ${e.sourceName} | observed ${e.observedAt} | ${e.label}` +
          (e.snippet ? ` | ${e.snippet}` : ""),
      )
      .join("\n") || "(no evidence provided)";

  return [
    `Company under review: ${ctx.instrument.name} (${ctx.instrument.symbol}) — sector ${ctx.instrument.sector}.`,
    ctx.priorThesis
      ? `Prior thesis on file: ${ctx.priorThesis}`
      : `No prior thesis on file.`,
    `Evidence pack — cite ONLY these evidence IDs:`,
    evidenceBlock,
    `Produce a fundamental assessment as JSON matching the required schema. Every claim.evidenceIds entry MUST be one of the IDs listed above.`,
  ].join("\n\n");
}

/** Assign deterministic IDs, turning the model draft into a core report. */
function finalize(
  draft: FundamentalReportDraft,
  ctx: FundamentalContext,
): FundamentalReport {
  return {
    id: `frp_${ctx.instrument.id}`,
    instrumentId: ctx.instrument.id,
    quality: draft.quality,
    valuation: draft.valuation,
    financialStrength: draft.financialStrength,
    catalysts: draft.catalysts,
    risks: draft.risks,
    claims: draft.claims.map((claim, index) => ({
      id: `clm_${ctx.instrument.id}_${index}`,
      ...claim,
    })),
  };
}

export const fundamentalAnalyst: Agent<
  FundamentalContext,
  FundamentalReportDraft,
  FundamentalReport
> = {
  def: {
    stage: "fundamental_analyst",
    instructions: INSTRUCTIONS,
    outputSchema: FundamentalReportDraftSchema,
    buildInput,
  },
  finalize,
};

import {
  MarketContextReportSchema,
  type Evidence,
  type Instrument,
  type MarketContextReport,
  type MaterialEvent,
  type Position,
} from "@sonar-ai/core";
import { z } from "zod";
import { ClaimDraftSchema, type Agent } from "./types";

/**
 * Market Context Analyst — evaluates the external world around the fund's
 * assets: news, sector, macro, competitors, regulation, and material events.
 *
 * Authority: explain material external context. It does NOT evaluate a single
 * company's fundamentals (that is the Fundamental Analyst), and it does NOT size
 * positions or turn one macro fact into a trade (that is the Portfolio Manager).
 * Runs once per committee run and produces one report.
 */

/** What the Market Context Analyst is allowed to see. Populated by the orchestrator. */
export interface MarketContextContext {
  /** The assets in scope (the candidate universe / selected set). */
  instruments: Instrument[];
  /** The material events driving this run. */
  materialEvents: MaterialEvent[];
  /**
   * The isolated, pre-fetched sector / macro / news evidence pack. The ONLY
   * window this agent has — it never sees the fundamental reports, the risk
   * report, or the mandate.
   */
  evidence: Evidence[];
  /** Current portfolio holdings, for framing (empty on the all-cash baseline). */
  holdings: Position[];
}

export const MarketContextReportDraftSchema = MarketContextReportSchema.omit({
  id: true,
  claims: true,
}).extend({ claims: z.array(ClaimDraftSchema) });
export type MarketContextReportDraft = z.infer<
  typeof MarketContextReportDraftSchema
>;

// ── First-draft prompt (Axel owns the final wording) ─────────────────────────

const INSTRUCTIONS = `You are the Market Context Analyst on an investment committee.

Assess the EXTERNAL context around the assets in scope, using ONLY the evidence
provided. Produce:
- summary: the one or two forces that matter most right now;
- drivers: the concrete external drivers (demand, policy, supply, cycle);
- sectorView: where the relevant sectors sit in their cycle;
- macroView: the macro and regulatory backdrop.

Then list claims. Every claim MUST cite one or more evidenceIds drawn ONLY from
the provided pack — never invent an ID or a fact. Mark each claim's stance as
"bull", "bear", "neutral", or "context".

Do NOT evaluate a single company's balance sheet in depth (Fundamental Analyst's
job) and do NOT propose weights or trades (Portfolio Manager's job). Return only
the required JSON.`;

function buildInput(ctx: MarketContextContext): string {
  const assets =
    ctx.instruments
      .map((i) => `- ${i.symbol} (${i.name}) — sector ${i.sector}`)
      .join("\n") || "(no assets in scope)";

  const events =
    ctx.materialEvents
      .map((e) => `- ${e.id} | ${e.headline} — ${e.summary} (${e.label})`)
      .join("\n") || "(no material events)";

  const holdings =
    ctx.holdings
      .map((p) => `- ${p.instrumentId} @ ${Math.round(p.weight * 100)}% of NAV`)
      .join("\n") || "(all cash — no holdings)";

  const evidenceBlock =
    ctx.evidence
      .map(
        (e) =>
          `- ${e.id} | ${e.title} | ${e.sourceName} | observed ${e.observedAt} | ${e.label}` +
          (e.snippet ? ` | ${e.snippet}` : ""),
      )
      .join("\n") || "(no evidence provided)";

  return [
    `Assets in scope:\n${assets}`,
    `Current holdings:\n${holdings}`,
    `Material events:\n${events}`,
    `Evidence pack — cite ONLY these evidence IDs:\n${evidenceBlock}`,
    `Produce a market-context assessment as JSON matching the required schema. Every claim.evidenceIds entry MUST be one of the IDs listed above.`,
  ].join("\n\n");
}

/** Assign deterministic IDs, turning the model draft into a core report. */
function finalize(draft: MarketContextReportDraft): MarketContextReport {
  return {
    id: "mrp_main",
    summary: draft.summary,
    drivers: draft.drivers,
    sectorView: draft.sectorView,
    macroView: draft.macroView,
    claims: draft.claims.map((claim, index) => ({
      id: `clm_mrp_${index}`,
      ...claim,
    })),
  };
}

export const marketContextAnalyst: Agent<
  MarketContextContext,
  MarketContextReportDraft,
  MarketContextReport
> = {
  def: {
    stage: "market_context",
    instructions: INSTRUCTIONS,
    outputSchema: MarketContextReportDraftSchema,
    buildInput,
  },
  finalize: (draft) => finalize(draft),
};

