import {
  BearCaseSchema,
  type BearCase,
  type Evidence,
  type FundamentalReport,
  type MarketContextReport,
  type Recommendation,
  type RiskReport,
} from "@sonar-ai/core";
import { z } from "zod";
import { ClaimDraftSchema, type Agent } from "./types";

/**
 * Bear/Critic — attacks the Portfolio Manager's proposal and names what could
 * make it fail.
 *
 * Authority: flag weak assumptions and failure scenarios. It CANNOT veto the
 * recommendation and CANNOT propose alternative sizing — it only surfaces risk
 * the committee should weigh before the human decides. Runs once, after the
 * proposal and the risk report.
 */

/** What the Bear/Critic is allowed to see. Populated by the orchestrator. */
export interface BearCriticContext {
  /** The recommendation under attack (the PM's proposal). */
  recommendation: Recommendation;
  /** Research summaries. */
  fundamentalReports: FundamentalReport[];
  marketContext: MarketContextReport | null;
  /** The Risk Officer's verdict on the proposal. */
  riskReport: RiskReport | null;
  /** The evidence records the critic may cite. */
  evidence: Evidence[];
}

export const BearCaseDraftSchema = BearCaseSchema.omit({
  id: true,
  targetRecommendationId: true,
  claims: true,
}).extend({ claims: z.array(ClaimDraftSchema) });
export type BearCaseDraft = z.infer<typeof BearCaseDraftSchema>;

// ── First-draft prompt (Axel owns the final wording) ─────────────────────────

const INSTRUCTIONS = `You are the Bear/Critic on an investment committee. Your job is to attack the proposed allocation.

Given the recommendation, the research, and the risk report, produce:
- weaknesses: the shakiest assumptions the proposal depends on;
- failureScenarios: concrete paths in which this allocation loses money;
- claims: specific criticisms, each citing evidenceIds from the provided list.

Be adversarial but fair — attack the reasoning, not a straw man. You CANNOT veto
the recommendation and you must NOT propose alternative weights or trades; you
only surface what the committee should weigh. Return only the required JSON.`;

function buildInput(ctx: BearCriticContext): string {
  const actions =
    ctx.recommendation.actions
      .map(
        (a) =>
          `- ${a.side} ${a.instrumentId} to ${Math.round(a.targetWeight * 100)}% of NAV`,
      )
      .join("\n") || "(no actions)";

  const pmCase = [
    `bull: ${ctx.recommendation.bull.map((c) => c.statement).join("; ") || "none"}`,
    `bear (self-identified): ${ctx.recommendation.bear.map((c) => c.statement).join("; ") || "none"}`,
  ].join("\n");

  const fundamentals =
    ctx.fundamentalReports
      .map((r) => `- ${r.instrumentId}: ${r.valuation}`)
      .join("\n") || "(none)";

  const risk = ctx.riskReport
    ? `Hard blocks: ${ctx.riskReport.hardBlocks.join(", ") || "none"}\n` +
      ctx.riskReport.checks
        .map((c) => `  · ${c.actionId}: ${c.result}${c.breachCode ? ` (${c.breachCode})` : ""}`)
        .join("\n")
    : "(no risk report)";

  const evidenceList =
    ctx.evidence.map((e) => `- ${e.id} | ${e.title}`).join("\n") || "(none)";

  return [
    `Recommendation under review (revision ${ctx.recommendation.revision}, confidence ${ctx.recommendation.confidence}):\n${actions}`,
    `Portfolio Manager's case:\n${pmCase}`,
    `Fundamental valuation notes:\n${fundamentals}`,
    `Market context:\n${ctx.marketContext ? ctx.marketContext.summary : "(none)"}`,
    `Risk Officer report:\n${risk}`,
    `Evidence you may cite:\n${evidenceList}`,
    `Produce the bear case as JSON matching the required schema. Every claim.evidenceIds entry MUST come from the evidence list above.`,
  ].join("\n\n");
}

/** Assign deterministic IDs and bind the case to the recommendation it targets. */
function finalize(draft: BearCaseDraft, ctx: BearCriticContext): BearCase {
  return {
    id: "bear_main",
    targetRecommendationId: ctx.recommendation.id,
    weaknesses: draft.weaknesses,
    failureScenarios: draft.failureScenarios,
    claims: draft.claims.map((claim, index) => ({
      id: `clm_bear_${index}`,
      ...claim,
    })),
  };
}

export const bearCritic: Agent<BearCriticContext, BearCaseDraft, BearCase> = {
  def: {
    stage: "bear_critic",
    instructions: INSTRUCTIONS,
    outputSchema: BearCaseDraftSchema,
    buildInput,
  },
  finalize,
};

import {
  CommitteeReportSchema,
  type CommitteeReport,
  type Evidence,
  type MaterialEvent,
  type PaperOrder,
  type PortfolioComparison,
  type Recommendation,
  type UserDecision,
} from "@sonar-ai/core";
import { z } from "zod";
import type { Agent } from "./types";

/**
 * Communications / Report Writer — turns the finished decision into a plain
 * narrative and a one-line summary.
 *
 * It runs ONLY after the human decision (enforced structurally: its context
 * requires a non-null `userDecision`) and it CANNOT influence allocation — its
 * output has no action or weight fields. Compliance disclaimers are injected by
 * `finalize`, never left to the model.
 */

/** What the Report Writer is allowed to see. Populated by the orchestrator. */
export interface ReportWriterContext {
  /** The final recommendation the human ruled on. */
  recommendation: Recommendation;
  /** The human's decision. Required — this agent never runs before it exists. */
  userDecision: UserDecision;
  /** The paper orders that actually applied (empty if rejected). */
  appliedOrders: PaperOrder[];
  /** The current-vs-proposed comparison. */
  comparison: PortfolioComparison;
  /** The originating event, for narrative color. */
  event?: MaterialEvent | null;
  /** Evidence records the narrative may reference. */
  evidence: Evidence[];
}

export const CommitteeReportDraftSchema = CommitteeReportSchema.omit({
  id: true,
});
export type CommitteeReportDraft = z.infer<typeof CommitteeReportDraftSchema>;

/** Always present, regardless of what the model writes. */
const REQUIRED_DISCLAIMERS = ["Paper trading only.", "Not investment advice."];

// ── First-draft prompt (Axel owns the final wording) ─────────────────────────

const INSTRUCTIONS = `You are the Communications / Report Writer on an investment committee. The decision is already made.

Write, in plain language:
- narrative: what the committee examined, what it found, and what was decided;
- decisionSummary: one sentence stating the outcome.

Describe only what happened. Do NOT recommend new trades, change any allocation,
or second-guess the decision — your role is to explain, not to decide. You may
add scenario-specific caveats to disclaimers, but standard compliance notices are
added automatically. Return only the required JSON.`;

function buildInput(ctx: ReportWriterContext): string {
  const outcome = ctx.userDecision.decision.toUpperCase();
  const actions =
    ctx.recommendation.actions
      .map((a) => `- ${a.side} ${a.instrumentId} to ${Math.round(a.targetWeight * 100)}% of NAV`)
      .join("\n") || "(no actions)";
  const applied =
    ctx.appliedOrders
      .map((o) => `- ${o.side} ${o.quantity} ${o.instrumentId} @ ${o.price.amount} (${o.notional.amount} ${o.notional.currency})`)
      .join("\n") || "(none applied)";

  return [
    `Human decision: ${outcome}${ctx.userDecision.note ? ` — "${ctx.userDecision.note}"` : ""}.`,
    ctx.event ? `Originating event: ${ctx.event.headline} — ${ctx.event.summary}` : `No specific event.`,
    `Recommended allocation:\n${actions}`,
    `Applied paper orders:\n${applied}`,
    `Cash after: ${ctx.comparison.proposedCash.amount} ${ctx.comparison.proposedCash.currency} of ${ctx.comparison.currentNav.amount} NAV.`,
    `Write the report as JSON matching the required schema.`,
  ].join("\n\n");
}

/** Assign the ID and force the mandatory compliance disclaimers. */
function finalize(draft: CommitteeReportDraft): CommitteeReport {
  const extra = draft.disclaimers.filter((d) => !REQUIRED_DISCLAIMERS.includes(d));
  return {
    id: "rpt_main",
    narrative: draft.narrative,
    decisionSummary: draft.decisionSummary,
    disclaimers: [...REQUIRED_DISCLAIMERS, ...extra],
  };
}

export const reportWriter: Agent<
  ReportWriterContext,
  CommitteeReportDraft,
  CommitteeReport
> = {
  def: {
    stage: "report_writer",
    instructions: INSTRUCTIONS,
    outputSchema: CommitteeReportDraftSchema,
    buildInput,
  },
  finalize: (draft) => finalize(draft),
};
